    private void selectFormat(String selected){if(challenge||format.equals(selected))return;wantScan=false;pendingPermission=false;stopCamera();if(session!=null&&!session.released()){error="Camera could not close. Reopen this screen before changing format.";render();return;}format=selected;hash="";scanState="idle";error="";render();}
    private void scanPressed(){if(!challenge&&enrollmentTab!=0)return;if(!resumed||!current()||!hasWindowFocus()||pendingPermission)return;error="";QrCameraAccess.Status permission=access.status(this);if(permission==QrCameraAccess.Status.READY){wantScan=true;begin();return;}if(challenge){error="Camera access is off. Use your Math fallback.";render();return;}if(permission==QrCameraAccess.Status.UNSUPPORTED){error="No supported camera is available.";render();return;}pendingPermission=true;settingsRequest=permission==QrCameraAccess.Status.SETTINGS;wantScan=true;try{access.request(this);if(access.status(this)==QrCameraAccess.Status.READY&&resumed){pendingPermission=false;begin();}}catch(RuntimeException unavailable){pendingPermission=false;wantScan=false;error="Camera access settings could not open. Try Android app settings.";render();}}
