    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] grants){super.onRequestPermissionsResult(request,permissions,grants);if(request==QrCameraAccess.REQUEST){boolean owned=pendingPermission&&wantScan&&!challenge&&enrollmentTab==0&&route.equals("code")&&!isFinishing()&&!isDestroyed();pendingPermission=false;settingsRequest=false;if(!owned)return;if(access.status(this)==QrCameraAccess.Status.READY){if(resumed)begin();}else{wantScan=false;error="Camera access was not allowed. You can keep editing and try again later.";render();}}}
